import React, { useCallback, useEffect, useRef, useState } from "react";
import axios from "axios";
import Editor from "@monaco-editor/react";
import {
  Activity,
  AlertCircle,
  ArrowLeft,
  CalendarDays,
  Check,
  ChevronDown,
  Code2,
  ExternalLink,
  Eye,
  FileCode2,
  Globe2,
  Home,
  Layers3,
  LineChart,
  Loader2,
  LogIn,
  LogOut,
  Menu,
  MessageSquare,
  Pencil,
  Play,
  Plus,
  RefreshCw,
  Rocket,
  Search,
  Shield,
  Sparkles,
  Star,
  Terminal,
  Trophy,
  User,
  Users,
  WalletCards,
  X,
} from "lucide-react";

const API_BASE_URL =
  process.env.REACT_APP_API_URL || "http://localhost:5000";

const STORAGE = {
  token: "devrank_token",
  user: "devrank_user",
};

const api = axios.create({
  baseURL: API_BASE_URL,
  timeout: 20000,
});

api.interceptors.request.use((config) => {
  const token = localStorage.getItem(STORAGE.token);

  if (token) {
    config.headers = config.headers || {};
    config.headers.Authorization = `Bearer ${token}`;
  }

  return config;
});

function apiMessage(
  error,
  fallback = "Server bilan bog‘lanishda xatolik yuz berdi."
) {
  if (error?.response?.data?.message) {
    return error.response.data.message;
  }

  if (error?.response?.status === 429) {
    return "Juda ko‘p so‘rov yuborildi. Bir ozdan keyin qayta urinib ko‘ring.";
  }

  if (error?.request) {
    return "Backend javob bermadi. http://localhost:5000 ishlayotganini tekshiring.";
  }

  return error?.message || fallback;
}

function cn(...items) {
  return items.filter(Boolean).join(" ");
}

function initials(name = "") {
  return (
    name
      .trim()
      .split(/\s+/)
      .slice(0, 2)
      .map((item) => item[0]?.toUpperCase() || "")
      .join("") || "DU"
  );
}

function formatScore(value) {
  return new Intl.NumberFormat("uz-UZ").format(
    Number(value || 0)
  );
}

function normalizeUser(raw) {
  const user = raw?.user || raw?.profile || raw || {};

  return {
    id: user.id || "",
    name: user.name || "",
    username: user.username || "",
    email: user.email || "",
    phone: user.phone || "",
    bio: user.bio || "",
    role: user.role || "Full Stack Developer",
    level: Number(user.level || 1),
    province: user.province || "",
    avatar: user.avatar || "",
    primaryCategory: user.primaryCategory || "web",
    score: Number(user.score || 0),
    rank: Number(user.rank || 0),
    projectsCount: Number(user.projectsCount || 0),
    followersCount: Number(user.followersCount || 0),
    topPercent: Number(user.topPercent || 100),
    growth: Number(user.growth || 0),
    online: Boolean(user.online),
    skills: Array.isArray(user.skills) ? user.skills : [],
    projects: Array.isArray(user.projects) ? user.projects : [],
  };
}

const CATEGORIES = [
  {
    id: "web",
    title: "Web-dasturlash",
    desc: "Frontend, backend, API va web arxitektura",
    icon: Globe2,
  },
  {
    id: "ai",
    title: "AI",
    desc: "Machine learning, LLM va AI systems",
    icon: Sparkles,
  },
  {
    id: "cyber",
    title: "Cyber Security",
    desc: "Security, OWASP, auth va AppSec",
    icon: Shield,
  },
  {
    id: "ux",
    title: "UI / UX",
    desc: "UX research, accessibility va design",
    icon: Layers3,
  },
];

const LANGUAGES = [
  ["javascript", "JavaScript", "js"],
  ["typescript", "TypeScript", "ts"],
  ["python", "Python", "py"],
  ["cpp", "C++", "cpp"],
  ["csharp", "C#", "cs"],
];

function Glass({
  children,
  className = "",
  onClick,
}) {
  const Tag = onClick ? "button" : "div";

  return (
    <Tag
      type={onClick ? "button" : undefined}
      onClick={onClick}
      className={cn(
        "w-full rounded-3xl border border-white/10 bg-white/[0.035] text-left",
        "shadow-[0_18px_55px_rgba(0,0,0,0.18)] backdrop-blur-xl",
        onClick &&
          "transition hover:border-white/20 hover:bg-white/[0.055]",
        className
      )}
    >
      {children}
    </Tag>
  );
}

function Button({
  children,
  icon: Icon,
  variant = "primary",
  disabled = false,
  className = "",
  onClick,
  type = "button",
}) {
  const styles = {
    primary:
      "bg-gradient-to-r from-violet-600 to-cyan-500 text-white shadow-lg shadow-violet-950/20",
    secondary:
      "border border-white/10 bg-white/[0.06] text-white hover:bg-white/[0.1]",
    ghost:
      "border border-transparent text-slate-300 hover:bg-white/[0.05]",
    danger:
      "border border-red-500/20 bg-red-500/10 text-red-300 hover:bg-red-500/15",
  };

  return (
    <button
      type={type}
      onClick={onClick}
      disabled={disabled}
      className={cn(
        "inline-flex items-center justify-center gap-2 rounded-2xl px-4 py-2.5",
        "text-sm font-semibold transition disabled:cursor-not-allowed",
        "disabled:opacity-50",
        styles[variant],
        className
      )}
    >
      {Icon ? (
        <Icon
          size={17}
          className={disabled ? "animate-spin" : ""}
        />
      ) : null}

      {children}
    </button>
  );
}

function Field({
  label,
  icon: Icon,
  error,
  ...props
}) {
  return (
    <label className="block">
      <div className="mb-2 flex justify-between text-xs text-slate-400">
        <span>{label}</span>

        {error ? (
          <span className="text-red-300">
            {error}
          </span>
        ) : null}
      </div>

      <div
        className={cn(
          "flex items-center gap-3 rounded-2xl border",
          "bg-white/[0.03] px-4 py-3",
          error
            ? "border-red-400/30"
            : "border-white/10"
        )}
      >
        {Icon ? (
          <Icon
            size={16}
            className="shrink-0 text-slate-500"
          />
        ) : null}

        <input
          {...props}
          className="w-full bg-transparent text-sm text-white outline-none placeholder:text-slate-600"
        />
      </div>
    </label>
  );
}

function Avatar({
  user,
  size = "md",
}) {
  const sizes = {
    sm: "h-9 w-9 text-xs",
    md: "h-11 w-11 text-sm",
    lg: "h-20 w-20 text-xl",
    xl: "h-24 w-24 text-2xl",
  };

  return (
    <div
      className={cn(
        "relative shrink-0 overflow-hidden rounded-2xl",
        "bg-gradient-to-br from-violet-500 via-fuchsia-500 to-cyan-400",
        "font-black text-white",
        sizes[size]
      )}
    >
      {user?.avatar ? (
        <img
          src={user.avatar}
          alt={user.name}
          className="h-full w-full object-cover"
        />
      ) : (
        <div className="flex h-full w-full items-center justify-center">
          {initials(user?.name)}
        </div>
      )}

      {user?.online ? (
        <span className="absolute bottom-0.5 right-0.5 h-3 w-3 rounded-full border-2 border-slate-950 bg-emerald-400" />
      ) : null}
    </div>
  );
}

function Progress({
  label,
  value,
}) {
  const number = Math.max(
    0,
    Math.min(100, Number(value) || 0)
  );

  return (
    <div>
      <div className="mb-2 flex justify-between text-xs">
        <span className="text-slate-400">
          {label}
        </span>

        <span className="text-white">
          {number}%
        </span>
      </div>

      <div className="h-2 overflow-hidden rounded-full bg-white/[0.06]">
        <div
          className="h-full rounded-full bg-gradient-to-r from-violet-500 to-cyan-400"
          style={{
            width: `${number}%`,
          }}
        />
      </div>
    </div>
  );
}

function Toasts({
  items,
  onRemove,
}) {
  return (
    <div className="pointer-events-none fixed right-4 top-4 z-[100] flex w-[calc(100%-2rem)] max-w-sm flex-col gap-3">
      {items.map((item) => (
        <div
          key={item.id}
          className={cn(
            "pointer-events-auto rounded-2xl border p-4 backdrop-blur-xl",
            item.type === "success"
              ? "border-emerald-400/20 bg-emerald-500/10"
              : "border-red-400/20 bg-red-500/10"
          )}
        >
          <div className="flex gap-3">
            <div className="mt-0.5">
              <AlertCircle
                size={16}
                className={
                  item.type === "success"
                    ? "text-emerald-300"
                    : "text-red-300"
                }
              />
            </div>

            <div className="min-w-0 flex-1">
              <div className="text-sm font-semibold">
                {item.title}
              </div>

              <div className="mt-1 text-xs leading-5 text-slate-400">
                {item.message}
              </div>
            </div>

            <button
              type="button"
              onClick={() =>
                onRemove(item.id)
              }
            >
              <X
                size={15}
                className="text-slate-500"
              />
            </button>
          </div>
        </div>
      ))}
    </div>
  );
}

function Header({
  eyebrow,
  title,
  subtitle,
  action,
}) {
  return (
    <div className="flex flex-col gap-4 md:flex-row md:items-end md:justify-between">
      <div>
        <div className="text-xs font-semibold uppercase tracking-[0.18em] text-violet-300">
          {eyebrow}
        </div>

        <h1 className="mt-2 text-3xl font-black sm:text-4xl">
          {title}
        </h1>

        <p className="mt-2 max-w-2xl text-sm leading-6 text-slate-500">
          {subtitle}
        </p>
      </div>

      {action ? (
        <div>{action}</div>
      ) : null}
    </div>
  );
}

function Empty({
  text,
  sub,
}) {
  return (
    <div className="mt-5 rounded-2xl border border-dashed border-white/10 p-10 text-center">
      <div className="text-sm font-semibold text-slate-400">
        {text}
      </div>

      <div className="mt-1 text-xs text-slate-600">
        {sub}
      </div>
    </div>
  );
}

function Stat({
  icon: Icon,
  label,
  value,
}) {
  return (
    <Glass className="p-5">
      <Icon
        size={18}
        className="text-violet-300"
      />

      <div className="mt-4 text-2xl font-black">
        {value}
      </div>

      <div className="mt-1 text-xs text-slate-600">
        {label}
      </div>
    </Glass>
  );
}

function Mini({
  label,
  value,
}) {
  return (
    <div className="rounded-2xl border border-white/8 bg-white/[0.02] p-3 text-center">
      <div className="text-lg font-black">
        {value}
      </div>

      <div className="mt-1 text-[10px] text-slate-600">
        {label}
      </div>
    </div>
  );
}

function LeaderRow({
  item,
  onClick,
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className="flex w-full items-center gap-3 rounded-2xl border border-white/8 bg-white/[0.02] p-3 text-left hover:bg-white/[0.04]"
    >
      <div className="w-8 text-center text-xs text-slate-600">
        #{item.rank}
      </div>

      <Avatar
        user={item}
        size="sm"
      />

      <div className="min-w-0 flex-1">
        <div className="truncate text-sm font-semibold">
          {item.name}
        </div>

        <div className="text-[11px] text-slate-600">
          {item.province || "—"}
        </div>
      </div>

      <div className="text-right">
        <div className="text-sm font-bold">
          {formatScore(item.score)}
        </div>

        <div className="text-[10px] text-slate-600">
          Level {item.level}
        </div>
      </div>
    </button>
  );
}

function ActionCard({
  title,
  desc,
  icon: Icon,
  onClick,
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className="rounded-2xl border border-white/10 bg-white/[0.025] p-4 text-left hover:bg-white/[0.05]"
    >
      <div className="flex items-center gap-3">
        <div className="rounded-xl bg-violet-500/10 p-2 text-violet-300">
          <Icon size={16} />
        </div>

        <div>
          <div className="text-sm font-semibold">
            {title}
          </div>

          <div className="mt-1 text-xs text-slate-600">
            {desc}
          </div>
        </div>
      </div>
    </button>
  );
}

function AuthView({
  onAuthenticated,
  toast,
}) {
  const [mode, setMode] = useState("login");

  const [form, setForm] = useState({
    name: "",
    email: "",
    phone: "",
    password: "",
  });

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  async function submit(event) {
    event.preventDefault();

    setError("");

    if (
      !form.email.trim() ||
      !form.email.includes("@")
    ) {
      setError("Email noto‘g‘ri.");
      return;
    }

    if (form.password.length < 6) {
      setError(
        "Parol kamida 6 ta belgidan iborat bo‘lsin."
      );
      return;
    }

    if (
      mode === "register" &&
      form.name.trim().length < 2
    ) {
      setError(
        "Ism kamida 2 ta belgidan iborat bo‘lsin."
      );
      return;
    }

    setLoading(true);

    try {
      const endpoint =
        mode === "login"
          ? "/api/login"
          : "/api/register";

      const payload =
        mode === "login"
          ? {
              email:
                form.email.trim(),
              password:
                form.password,
            }
          : {
              name: form.name.trim(),
              email:
                form.email.trim(),
              phone:
                form.phone.trim(),
              password:
                form.password,
            };

      const response =
        await api.post(
          endpoint,
          payload
        );

      const token =
        response.data.token;

      const nextUser =
        normalizeUser(
          response.data.user
        );

      localStorage.setItem(
        STORAGE.token,
        token
      );

      localStorage.setItem(
        STORAGE.user,
        JSON.stringify(
          nextUser
        )
      );

      onAuthenticated(
        nextUser
      );

      toast(
        "success",
        mode === "login"
          ? "Xush kelibsiz"
          : "Profil yaratildi",
        "Ma’lumotlar serverga saqlandi."
      );
    } catch (requestError) {
      setError(
        apiMessage(
          requestError
        )
      );
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="min-h-screen bg-[#07080e] px-4 py-8 text-white">
      <div className="mx-auto grid min-h-[90vh] max-w-6xl items-stretch overflow-hidden rounded-[32px] border border-white/10 bg-white/[0.025] lg:grid-cols-2">
        <div className="hidden flex-col justify-between border-r border-white/10 p-10 lg:flex">
          <div>
            <div className="flex items-center gap-3">
              <div className="rounded-2xl bg-gradient-to-br from-violet-600 to-cyan-500 p-3">
                <Code2 size={22} />
              </div>

              <div className="text-xl font-black">
                DevRank{" "}
                <span className="text-violet-400">
                  UZ
                </span>
              </div>
            </div>

            <div className="mt-24 max-w-xl">
              <div className="text-xs font-semibold uppercase tracking-[0.2em] text-violet-300">
                Developer Network
              </div>

              <h1 className="mt-5 text-6xl font-black leading-[0.98]">
                Coding natijangizni{" "}
                <span className="bg-gradient-to-r from-violet-300 to-cyan-300 bg-clip-text text-transparent">
                  reytingga aylantiring.
                </span>
              </h1>

              <p className="mt-6 text-slate-400">
                Real PostgreSQL leaderboard,
                challenges, portfolio va
                Gemini AI evaluation.
              </p>
            </div>
          </div>

          <div className="grid grid-cols-3 gap-3">
            <Glass className="p-4">
              <div className="text-xs text-slate-500">
                Users
              </div>

              <div className="mt-2 text-2xl font-black">
                Real
              </div>
            </Glass>

            <Glass className="p-4">
              <div className="text-xs text-slate-500">
                Projects
              </div>

              <div className="mt-2 text-2xl font-black">
                Real
              </div>
            </Glass>

            <Glass className="p-4">
              <div className="text-xs text-slate-500">
                AI
              </div>

              <div className="mt-2 text-2xl font-black">
                Gemini
              </div>
            </Glass>
          </div>
        </div>

        <div className="flex items-center p-6 sm:p-10">
          <div className="mx-auto w-full max-w-md">
            <div className="mb-7">
              <div className="text-xs text-slate-500">
                DevRank UZ
              </div>

              <h2 className="mt-2 text-3xl font-black">
                {mode === "login"
                  ? "Hisobingizga kiring"
                  : "Developer profil yarating"}
              </h2>
            </div>

            <div className="mb-5 grid grid-cols-2 rounded-2xl border border-white/10 bg-white/[0.03] p-1">
              <button
                type="button"
                onClick={() =>
                  setMode("login")
                }
                className={cn(
                  "rounded-xl px-4 py-2.5 text-sm font-semibold",
                  mode === "login"
                    ? "bg-white/[0.08]"
                    : "text-slate-500"
                )}
              >
                Login
              </button>

              <button
                type="button"
                onClick={() =>
                  setMode("register")
                }
                className={cn(
                  "rounded-xl px-4 py-2.5 text-sm font-semibold",
                  mode === "register"
                    ? "bg-white/[0.08]"
                    : "text-slate-500"
                )}
              >
                Register
              </button>
            </div>

            <form
              onSubmit={submit}
              className="space-y-4"
            >
              {mode === "register" ? (
                <Field
                  label="To‘liq ism"
                  icon={User}
                  value={form.name}
                  onChange={(event) =>
                    setForm({
                      ...form,
                      name:
                        event.target
                          .value,
                    })
                  }
                  placeholder="Ismingiz"
                />
              ) : null}

              <Field
                label="Email"
                icon={Globe2}
                type="email"
                value={form.email}
                onChange={(event) =>
                  setForm({
                    ...form,
                    email:
                      event.target
                        .value,
                  })
                }
                placeholder="you@example.com"
              />

              {mode === "register" ? (
                <Field
                  label="Telefon"
                  icon={Activity}
                  value={form.phone}
                  onChange={(event) =>
                    setForm({
                      ...form,
                      phone:
                        event.target
                          .value,
                    })
                  }
                  placeholder="+998 90 123 45 67"
                />
              ) : null}

              <Field
                label="Parol"
                icon={Shield}
                type="password"
                value={form.password}
                onChange={(event) =>
                  setForm({
                    ...form,
                    password:
                      event.target
                        .value,
                  })
                }
                placeholder="Kamida 6 ta belgi"
              />

              {error ? (
                <div className="rounded-2xl border border-red-400/20 bg-red-500/5 p-3 text-xs text-red-300">
                  {error}
                </div>
              ) : null}

              <Button
                type="submit"
                className="w-full py-3.5"
                disabled={loading}
                icon={
                  loading
                    ? Loader2
                    : mode === "login"
                    ? LogIn
