function CodeLab({
  toast,
  refreshUser,
}) {
  const [
    category,
    setCategory,
  ] = useState("web");

  const [
    challenges,
    setChallenges,
  ] = useState([]);

  const [
    selected,
    setSelected,
  ] = useState(null);

  const [
    language,
    setLanguage,
  ] = useState("javascript");

  const [
    code,
    setCode,
  ] = useState("");

  const [
    quizAnswer,
    setQuizAnswer,
  ] = useState(null);

  const [
    result,
    setResult,
  ] = useState(null);

  const [
    loading,
    setLoading,
  ] = useState(false);

  const load = useCallback(
    async () => {
      try {
        const response =
          await api.get(
            "/api/challenges",
            {
              params: {
                category,
              },
            }
          );

        setChallenges(
          Array.isArray(
            response.data?.items
          )
            ? response.data.items
            : []
        );
      } catch (error) {
        setChallenges([]);

        toast(
          "error",
          "Challenge xatosi",
          apiMessage(error)
        );
      }
    },
    [category, toast]
  );

  useEffect(() => {
    load();

    setSelected(null);
    setResult(null);
    setQuizAnswer(null);
  }, [load]);

  async function openChallenge(
    item
  ) {
    try {
      const response =
        await api.get(
          `/api/challenges/${item.id}`
        );

      const challenge =
        response.data?.challenge ||
        response.data;

      setSelected(
        challenge
      );

      setCode(
        challenge.starterCode || ""
      );

      setLanguage(
        challenge.language ||
          "javascript"
      );

      setQuizAnswer(null);
      setResult(null);
    } catch (error) {
      toast(
        "error",
        "Challenge",
        apiMessage(error)
      );
    }
  }

  async function submit() {
    if (
      !selected ||
      loading
    ) {
      return;
    }

    if (
      selected.type ===
        "QUIZ" &&
      quizAnswer === null
    ) {
      toast(
        "error",
        "Javob tanlang",
        "Quiz variantini belgilang."
      );

      return;
    }

    if (
      selected.type !==
        "QUIZ" &&
      !code.trim()
    ) {
      toast(
        "error",
        "Kod bo‘sh",
        "Kod yozing."
      );

      return;
    }

    setLoading(true);
    setResult(null);

    try {
      const payload =
        selected.type ===
        "QUIZ"
          ? {
              answer:
                Number(
                  quizAnswer
                ),
            }
          : {
              code,
              language,
            };

      const response =
        await api.post(
          `/api/challenges/${selected.id}/submit`,
          payload
        );

      setResult(
        response.data
      );

      await refreshUser();

      await load();

      toast(
        "success",
        response.data?.passed
          ? "Challenge o‘tdi"
          : "Kod baholandi",
        `Natija: ${
          response.data
            ?.score ?? 0
        }/100`
      );
    } catch (error) {
      toast(
        "error",
        "Submit xatosi",
        apiMessage(error)
      );
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="space-y-7">
      <Header
        eyebrow="AI Code Lab"
        title="Challenge'lar"
        subtitle="Web, AI, Cyber Security va UI/UX bo‘yicha database challenge va quizlar."
      />

      <div className="grid gap-3 md:grid-cols-4">
        {CATEGORIES.map(
          (item) => {
            const Icon =
              item.icon;

            return (
              <button
                key={item.id}
                type="button"
                onClick={() =>
                  setCategory(
                    item.id
                  )
                }
                className={cn(
                  "rounded-2xl border p-4 text-left",
                  category ===
                    item.id
                    ? "border-violet-400/30 bg-violet-500/10"
                    : "border-white/10 bg-white/[0.03]"
                )}
              >
                <Icon
                  size={17}
                  className="text-violet-300"
                />

                <div className="mt-3 text-sm font-bold">
                  {item.title}
                </div>

                <div className="mt-1 text-[11px] text-slate-600">
                  {item.desc}
                </div>
              </button>
            );
          }
        )}
      </div>

      {!selected ? (
        <Glass className="p-6">
          <div className="flex items-center justify-between">
            <div>
              <div className="text-xl font-bold">
                {
                  CATEGORIES.find(
                    (item) =>
                      item.id ===
