  refreshUser,
}) {
  const [editing, setEditing] =
    useState(false);

  const [project, setProject] =
    useState(null);

  const [form, setForm] =
    useState({
      name: user.name,
      phone: user.phone,
      bio: user.bio,
      skills:
        user.skills.join(
          ", "
        ),
    });

  useEffect(() => {
    setForm({
      name: user.name,
      phone: user.phone,
      bio: user.bio,
      skills:
        user.skills.join(
          ", "
        ),
    });
  }, [user]);

  async function saveProfile(
    event
  ) {
    event.preventDefault();

    try {
      const response =
        await api.patch(
          "/api/profile",
          {
            name: form.name,
            phone: form.phone,
            bio: form.bio,
            technologies:
              form.skills
                .split(",")
                .map((item) =>
                  item.trim()
                )
                .filter(Boolean),
          }
        );

      const next =
        normalizeUser(
          response.data
            ?.user
        );

      localStorage.setItem(
        STORAGE.user,
        JSON.stringify(next)
      );

      await refreshUser();

      setEditing(false);

      toast(
        "success",
        "Profil saqlandi",
        "Ma’lumotlar PostgreSQL'ga yozildi."
      );
    } catch (error) {
      toast(
        "error",
        "Profil xatosi",
        apiMessage(error)
      );
    }
  }

