function ProjectModal({
  project,
  onClose,
  onSaved,
  toast,
}) {
  const editing =
    Boolean(project?.id);

  const [form, setForm] =
    useState({
      title:
        project?.title ||
        "",
      description:
        project?.description ||
        "",
      purpose:
        project?.purpose ||
        "",
      problem:
        project?.problem ||
        "",
      technologies: (
        project?.technologies ||
        []
      ).join(", "),
      githubUrl:
        project?.githubUrl ||
        "",
      liveUrl:
        project?.liveUrl ||
        "",
    });

  const [
    files,
    setFiles,
  ] = useState([]);

  const [
    loading,
    setLoading,
  ] = useState(false);

  async function save(
    event
  ) {
    event.preventDefault();

    if (
      !form.title.trim() ||
      !form.description.trim() ||
      !form.purpose.trim() ||
      !form.problem.trim()
    ) {
      toast(
        "error",
        "Loyiha",
        "Nom, tavsif, maqsad va muammo majburiy."
      );

      return;
    }

    const existingImages =
      project?.images
        ?.length || 0;

    const remaining =
      Math.max(
        0,
        5 -
          existingImages
      );

    setLoading(true);

    try {
      const fd =
        new FormData();

      fd.append(
        "title",
        form.title
      );

      fd.append(
        "description",
        form.description
      );

      fd.append(
        "purpose",
        form.purpose
      );

      fd.append(
        "problem",
        form.problem
      );

      fd.append(
        "technologies",
        JSON.stringify(
          form.technologies
            .split(",")
            .map(
              (item) =>
                item.trim()
            )
            .filter(Boolean)
        )
      );

      fd.append(
        "githubUrl",
        form.githubUrl
      );

      fd.append(
        "liveUrl",
        form.liveUrl
      );

      files
        .slice(0, remaining)
        .forEach(
          (file) => {
            fd.append(
              "images",
              file
            );
          }
        );

      const response =
        editing
          ? await api.patch(
              `/api/projects/${project.id}`,
              fd,
              {
                headers: {
                  "Content-Type":
                    "multipart/form-data",
                },
              }
            )
          : await api.post(
              "/api/projects",
              fd,
              {
                headers: {
                  "Content-Type":
                    "multipart/form-data",
                },
              }
            );

      await onSaved(
        response.data
          ?.project
      );

      toast(
        "success",
        editing
          ? "Loyiha yangilandi"
          : "Loyiha qo‘shildi",
        "Portfolio ma’lumotlari saqlandi."
      );
    } catch (error) {
      toast(
        "error",
        "Portfolio xatosi",
        apiMessage(error)
      );
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="fixed inset-0 z-[85] flex items-center justify-center bg-black/70 p-4">
      <div className="max-h-[92vh] w-full max-w-3xl overflow-auto rounded-3xl border border-white/10 bg-[#0d0e15] p-6">
        <div className="flex items-center justify-between">
          <div>
            <div className="text-xl font-bold">
              {editing
                ? "Loyihani tahrirlash"
                : "Yangi loyiha"}
            </div>

            <div className="mt-1 text-xs text-slate-600">
              PostgreSQL + file storage
            </div>
          </div>

          <button
            type="button"
            onClick={onClose}
          >
            <X size={18} />
          </button>
        </div>

        <form
          onSubmit={save}
          className="mt-5 space-y-4"
        >
          <div className="grid gap-4 md:grid-cols-2">
            <Field
              label="Loyiha nomi"
              value={
                form.title
              }
              onChange={(event) =>
                setForm({
                  ...form,
                  title:
                    event.target
                      .value,
                })
              }
            />

            <Field
              label="Texnologiyalar"
              value={
                form.technologies
              }
              onChange={(event) =>
                setForm({
                  ...form,
                  technologies:
                    event.target
                      .value,
                })
              }
              placeholder="React, Node.js, PostgreSQL"
            />
          </div>

          <Textarea
            label="Nima qiladi?"
            value={
              form.description
            }
            onChange={(value) =>
              setForm({
                ...form,
                description:
                  value,
              })
            }
          />

          <Textarea
            label="Nega yaratildi?"
            value={
              form.purpose
            }
            onChange={(value) =>
              setForm({
                ...form,
                purpose:
                  value,
              })
            }
          />

          <Textarea
            label="Qaysi muammoni hal qiladi?"
            value={
              form.problem
            }
            onChange={(value) =>
              setForm({
                ...form,
                problem:
                  value,
              })
            }
          />

          <div className="grid gap-4 md:grid-cols-2">
            <Field
              label="GitHub URL"
              value={
                form.githubUrl
              }
              onChange={(event) =>
                setForm({
                  ...form,
                  githubUrl:
                    event.target
                      .value,
                })
              }
              placeholder="https://github.com/..."
            />

            <Field
              label="Live URL"
              value={
                form.liveUrl
              }
              onChange={(event) =>
                setForm({
                  ...form,
                  liveUrl:
                    event.target
                      .value,
                })
              }
              placeholder="https://..."
            />
          </div>

          <div>
            <div className="mb-2 text-xs text-slate-400">
              Rasmlar — 5 tagacha
            </div>

            <input
              type="file"
              accept="image/png,image/jpeg,image/webp,image/gif"
              multiple
              onChange={(event) =>
                setFiles(
                  Array.from(
                    event.target
                      .files ||
                      []
                  )
                )
              }
              className="w-full text-xs text-slate-500"
            />
          </div>

          <div className="flex justify-end gap-2">
            <Button
              variant="ghost"
              onClick={onClose}
            >
              Bekor qilish
            </Button>

            <Button
              type="submit"
              disabled={loading}
              icon={
                loading
                  ? Loader2
                  : Check
              }
            >
              {loading
                ? "Saqlanmoqda..."
                : "Saqlash"}
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
}

