function MessagesView({
  toast,
}) {
  const [items, setItems] =
    useState([]);

  const [loading, setLoading] =
    useState(true);

  const load = useCallback(
    async () => {
      setLoading(true);

      try {
        const response =
          await api.get(
            "/api/messages"
          );

        setItems(
          response.data?.items ||
            []
        );
      } catch (error) {
        toast(
          "error",
          "Xabarlar xatosi",
          apiMessage(error)
        );
      } finally {
        setLoading(false);
      }
    },
    [toast]
  );

  useEffect(() => {
    load();
  }, [load]);

  async function markRead(
    id
  ) {
    try {
      await api.post(
        `/api/messages/${id}/read`
      );

      setItems(
        (previous) =>
          previous.map(
            (item) =>
              item.id === id
                ? {
                    ...item,
                    read: true,
                  }
                : item
          )
      );
    } catch {
      // Read failure is non-critical.
    }
  }

  return (
    <div className="space-y-8">
      <Header
        eyebrow="Inbox"
        title="Xabarlar"
        subtitle="Profil, challenge va server hodisalaridan notificationlar."
        action={
          <Button
            variant="secondary"
            onClick={load}
            icon={RefreshCw}
          >
            Yangilash
          </Button>
        }
      />

      <Glass className="p-6">
        {loading ? (
          <div className="py-12 text-center text-sm text-slate-600">
            Yuklanmoqda...
          </div>
        ) : items.length ===
          0 ? (
          <Empty
            text="Hali xabarlar yo‘q"
            sub="Backend message yaratganda shu yerda chiqadi."
          />
        ) : (
          <div className="space-y-3">
            {items.map(
              (item) => (
                <button
                  key={item.id}
                  type="button"
                  onClick={() =>
                    markRead(
                      item.id
                    )
                  }
                  className={cn(
                    "block w-full rounded-2xl border p-4 text-left",
                    item.read
                      ? "border-white/8 bg-white/[0.02]"
                      : "border-violet-400/20 bg-violet-500/5"
                  )}
                >
                  <div className="flex items-start gap-3">
                    <MessageSquare
                      size={17}
                      className="mt-0.5 text-violet-300"
                    />

                    <div className="min-w-0 flex-1">
                      <div className="text-sm font-semibold">
                        {
                          item.title
                        }
                      </div>

                      <div className="mt-1 text-xs leading-6 text-slate-500">
                        {
                          item.body
                        }
                      </div>

                      <div className="mt-2 text-[10px] text-slate-700">
                        {new Date(
                          item.createdAt
                        ).toLocaleString(
                          "uz-UZ"
                        )}
                      </div>
                    </div>

                    {!item.read ? (
                      <span className="mt-1 h-2 w-2 rounded-full bg-violet-400" />
                    ) : null}
                  </div>
                </button>
              )
            )}
          </div>
        )}
      </Glass>
    </div>
  );
}

function App() {
  const [user, setUser] =
    useState(() => {
      try {
        const saved =
          localStorage.getItem(
            STORAGE.user
          );

        return saved
          ? normalizeUser(
              JSON.parse(
                saved
              )
            )
          : null;
      } catch {
        return null;
      }
    });

  const [view, setView] =
    useState(
      "dashboard"
    );

  const [
    toasts,
    setToasts,
  ] = useState([]);

  const [
    mobileOpen,
    setMobileOpen,
  ] = useState(false);

  const [
    leaderboard,
    setLeaderboard,
  ] = useState([]);

  const [
    profileOverride,
    setProfileOverride,
  ] = useState(null);

  const [
    loadingUser,
    setLoadingUser,
  ] = useState(
    Boolean(user)
  );

  const toast = useCallback(
    (
      type,
      title,
      message
    ) => {
      const id = `${Date.now()}-${Math.random()}`;

      setToasts(
        (previous) => [
          ...previous,
          {
            id,
            type,
            title,
            message,
          },
        ]
      );

      window.setTimeout(
        () => {
          setToasts(
            (previous) =>
              previous.filter(
                (item) =>
                  item.id !==
                  id
              )
          );
        },
        5000
      );
    },
    []
  );

  const refreshUser =
    useCallback(
      async () => {
        const token =
          localStorage.getItem(
            STORAGE.token
          );

        if (!token) {
          return null;
        }

        try {
          const response =
            await api.get(
              "/api/profile"
            );

          const next =
            normalizeUser(
              response.data
                ?.user
            );

          setUser(next);

          localStorage.setItem(
            STORAGE.user,
            JSON.stringify(
              next
            )
          );

          return next;
        } catch (error) {
          if (
            error?.response
              ?.status === 401
          ) {
            logout();
          }

          throw error;
        } finally {
          setLoadingUser(false);
        }
      },
      []
    );

  const loadLeaderboard =
    useCallback(
      async () => {
        const token =
          localStorage.getItem(
            STORAGE.token
          );

        if (!token) {
          return;
        }

        try {
          const response =
            await api.get(
              "/api/leaderboard"
            );

          setLeaderboard(
            Array.isArray(
              response.data?.users
            )
              ? response.data.users
              : []
          );
        } catch {
          setLeaderboard([]);
        }
      },
      []
    );

  useEffect(() => {
    if (!user) {
      return;
    }

    refreshUser().catch(
      () => {}
    );

    loadLeaderboard();
  }, [
    user,
    refreshUser,
    loadLeaderboard,
  ]);

  function logout() {
    localStorage.removeItem(
      STORAGE.token
    );

    localStorage.removeItem(
      STORAGE.user
    );

    setUser(null);
    setProfileOverride(null);
    setLeaderboard([]);
  }

  function onAuthenticated(
    nextUser
  ) {
    setUser(
      normalizeUser(
        nextUser
      )
    );

    setView(
      "dashboard"
    );
  }

  async function openProfile(
    id
  ) {
    try {
      const response =
        await api.get(
          `/api/users/${id}`
        );

      setProfileOverride(
        normalizeUser(
          response.data
            ?.user
        )
      );

      setView(
        "profile"
      );
    } catch (error) {
      toast(
        "error",
        "Profil",
        apiMessage(error)
      );
    }
  }

  function renderPage() {
    if (
      view ===
      "leaderboard"
    ) {
      return (
        <LeaderboardView
          toast={toast}
          onOpenProfile={
            openProfile
          }
        />
      );
    }

    if (
      view === "code"
    ) {
      return (
        <CodeLab
          toast={toast}
          refreshUser={
            refreshUser
          }
        />
      );
    }

    if (
      view === "profile"
    ) {
      const target =
        profileOverride ||
        user;

      return (
        <ProfileView
          user={target}
          own={
            !profileOverride ||
            profileOverride.id ===
              user.id
          }
          toast={toast}
          refreshUser={
            refreshUser
          }
        />
      );
    }

    if (
      view ===
      "content"
    ) {
      return (
        <ContentView
          toast={toast}
        />
      );
    }

    if (
      view ===
      "messages"
    ) {
      return (
        <MessagesView
          toast={toast}
        />
      );
    }

    return (
      <DashboardView
        user={user}
        leaderboard={
          leaderboard
        }
        setView={setView}
      />
    );
  }

  if (!user) {
    return (
      <>
        <AuthView
          onAuthenticated={
            onAuthenticated
          }
          toast={toast}
        />

        <Toasts
          items={toasts}
          onRemove={(id) =>
            setToasts(
              (previous) =>
                previous.filter(
                  (item) =>
                    item.id !== id
                )
            )
          }
        />
      </>
    );
  }

  if (loadingUser) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-[#07080e] text-slate-500">
        <Loader2 className="animate-spin" />
        <span className="ml-2">
          Profil yuklanmoqda...
        </span>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#07080e] text-white">
      <Sidebar
        view={view}
        setView={(next) => {
          setProfileOverride(
            null
          );
          setView(next);
        }}
        onLogout={logout}
        user={user}
        mobileOpen={
          mobileOpen
        }
        setMobileOpen={
          setMobileOpen
        }
      />

      <div className="lg:pl-[260px]">
        <Topbar
          user={user}
          onMenu={() =>
            setMobileOpen(
              true
            )
          }
          onProfile={() => {
            setProfileOverride(
              null
            );
            setView(
              "profile"
            );
          }}
          onSearch={(query) =>
            toast(
              "success",
              "Qidiruv",
              `Qidiruv: ${query}`
            )
          }
        />

        <main className="mx-auto max-w-[1480px] px-4 py-8 sm:px-6 lg:px-8">
          {renderPage()}
        </main>
      </div>

      <Toasts
        items={toasts}
        onRemove={(id) =>
          setToasts(
            (previous) =>
              previous.filter(
                (item) =>
                  item.id !== id
              )
          )
        }
      />
    </div>
  );
}

export default App;
